CREATE TABLE IF NOT EXISTS agent_skills (
  id           TEXT PRIMARY KEY,
  agent_id     TEXT NOT NULL,
  slug         TEXT NOT NULL,
  name         TEXT NOT NULL,
  version      TEXT NOT NULL DEFAULT '1.0',
